12	import org.springframework.samples.petclinic.repository.OwnerRepository;
13	
14	/**
15	 * Assigns the owner's {@code memberId}, formatted {@code <REGION><FY><HASH8><CHK>} where REGION is
16	 * the version-2 region code derived from the postcode (the plain region with the fixed {@code V2}
17	 * version tag appended, e.g. {@code NSWV2}; see {@link OwnerLocality#regionCodeV2}), FY is the 2-digit fiscal
18	 * year of the owner's (business-day-adjusted) registration date (see {@link FiscalYear}), HASH8 is
19	 * the first eight upper-case hex characters of SHA-256 over {@code normalizedTelephone + lastName},
20	 * and CHK is a single Luhn check digit computed over
21	 * the digits of {@code <REGION><FY><HASH8>}. The telephone is normalized to E.164 (see
22	 * {@link TelephoneE164}) exactly as the owner is stored, so the hash is stable regardless of the
23	 * telephone's input format. This single field replaces the former {@code customerCode} and
24	 * {@code membershipNumber}.
25	 *
26	 * <p>Should that computed memberId collide with an existing owner's {@code memberId}, it is
27	 * de-duplicated by appending {@code -<n>} with the smallest {@code n} of 2 or more that makes it
28	 * unique. Runs before {@link SaveOwner}, so the owner being created is not matched against itself.
29	 */
30	public class AssignMemberId {
31	
32	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
33	        String region = OwnerLocality.regionCodeV2(owner.getCity(), owner.getPostcode());
34	        String fy = FiscalYear.twoDigit(owner.getRegistrationDate());
35	        String normalizedTelephone = normalizedTelephone(owner.getTelephone());
36	        String hash8 = sha256Hex8(normalizedTelephone + owner.getLastName());
37	        String base = region + fy + hash8;
38	        String memberId = base + luhnCheckDigit(base);
39	        owner.setMemberId(deduplicate(memberId, ownerRepository));
40	    }
41	
42	    /**
43	     * Returns {@code baseId} if no existing owner already uses it; otherwise appends {@code -<n>}
44	     * with the smallest {@code n >= 2} that is not taken by any existing owner.
45	     */
46	    private static String deduplicate(String baseId, OwnerRepository ownerRepository) {
47	        Set<String> existing = new HashSet<>();
48	        for (Owner other : ownerRepository.findAll()) {
49	            String id = other.getMemberId();
50	            if (id != null) {
51	                existing.add(id);
52	            }
53	        }
54	        if (!existing.contains(baseId)) {
55	            return baseId;
56	        }
57	        for (int n = 2; ; n++) {
58	            String candidate = baseId + "-" + n;
59	            if (!existing.contains(candidate)) {
60	                return candidate;
61	            }
62	        }
63	    }
64	
65	    /** Single Luhn check digit (0 to 9) over the digits contained in {@code value}; non-digits ignored. */
66	    private static int luhnCheckDigit(String value) {
67	        int sum = 0;
68	        boolean dbl = true;
69	        for (int i = value.length() - 1; i >= 0; i--) {
70	            char c = value.charAt(i);
71	            if (c < '0' || c > '9') {
72	                continue;
73	            }
74	            int d = c - '0';
75	            if (dbl) {
76	                d *= 2;
77	                if (d > 9) {
78	                    d -= 9;
79	                }
80	            }
81	            sum += d;
82	            dbl = !dbl;
83	        }
84	        return (10 - (sum % 10)) % 10;
85	    }
86	
87	    /** The owner's telephone in the same canonical E.164 form it is stored with. */
88	    private static String normalizedTelephone(String telephone) {
89	        String e164 = TelephoneE164.toE164(telephone);
90	        return e164 != null ? e164 : (telephone == null ? "" : telephone);
91	    }
92	
93	    /** First eight upper-case hex characters of SHA-256 over the UTF-8 bytes of {@code value}. */
94	    private static String sha256Hex8(String value) {
95	        byte[] digest;
96	        try {
97	            digest = MessageDigest.getInstance("SHA-256")
98	                    .digest(value.getBytes(StandardCharsets.UTF_8));
99	        }
100	        catch (NoSuchAlgorithmException ex) {
101	            throw new IllegalStateException("SHA-256 not available", ex); // never on a standard JRE
102	        }
103	        StringBuilder sb = new StringBuilder(8);
104	        for (int i = 0; i < 4; i++) {
105	            sb.append(String.format("%02X", digest[i]));
106	        }
107	        return sb.toString().toUpperCase(Locale.ROOT);
108	    }
109	}
